import { checkExceptions, createWaiter, WaiterState, } from "@smithy/core/client";
import { GetHealthCheckSourceCommand, } from "../commands/GetHealthCheckSourceCommand";
const checkState = async (client, input) => {
    let reason;
    try {
        let result = await client.send(new GetHealthCheckSourceCommand(input));
        reason = result;
        try {
            const returnComparator = () => {
                return result.HealthCheckSource.HealthCheckSourceStatus;
            };
            if (returnComparator() === "CREATE_COMPLETED") {
                return { state: WaiterState.SUCCESS, reason };
            }
        }
        catch (e) { }
        try {
            const returnComparator = () => {
                return result.HealthCheckSource.HealthCheckSourceStatus;
            };
            if (returnComparator() === "CREATE_FAILED") {
                return { state: WaiterState.FAILURE, reason };
            }
        }
        catch (e) { }
    }
    catch (exception) {
        reason = exception;
        if (exception.name === "NoSuchHealthCheckSource") {
            return { state: WaiterState.RETRY, reason };
        }
    }
    return { state: WaiterState.RETRY, reason };
};
export const waitForHealthCheckSourceCreated = async (params, input) => {
    const serviceDefaults = { minDelay: 15, maxDelay: 120 };
    return createWaiter({ ...serviceDefaults, ...params }, input, checkState);
};
export const waitUntilHealthCheckSourceCreated = async (params, input) => {
    const serviceDefaults = { minDelay: 15, maxDelay: 120 };
    const result = await createWaiter({ ...serviceDefaults, ...params }, input, checkState);
    return checkExceptions(result);
};
